import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import Avatar from 'flarum/common/components/Avatar';
import { startDiscussion, t } from '../util';

/** The phone's bottom bar (CSS shows it under 768px). Mounted once, outside the page. */
export default class HudBar extends Component {
  view() {
    const user = app.session.user;
    const route = app.current.get('routeName');
    const unread = user ? user.unreadNotificationCount?.() || 0 : 0;
    const tags = 'flarum-tags' in flarum.extensions;
    const hidden = app.composer.isVisible?.() && app.composer.position !== 'minimized';
    return m("nav", {
      className: 'DuskHud' + (hidden ? ' is-hidden' : ''),
      "aria-label": String(t('hud.label'))
    }, m(Link, {
      href: app.route('index'),
      className: 'DuskHud-item' + (route === 'index' ? ' is-active' : '')
    }, m(Icon, {
      name: "fas fa-house"
    }), m("span", null, t('hud.home'))), tags ? m(Link, {
      href: app.route('tags'),
      className: 'DuskHud-item' + (route === 'tags' ? ' is-active' : '')
    }, m(Icon, {
      name: "fas fa-tags"
    }), m("span", null, t('hud.tags'))) : null, m("button", {
      type: "button",
      className: "DuskHud-new",
      onclick: startDiscussion,
      "aria-label": String(app.translator.trans('core.forum.index.start_discussion_button'))
    }, m(Icon, {
      name: "fas fa-plus"
    })), user ? m(Link, {
      href: app.route('notifications'),
      className: 'DuskHud-item' + (route === 'notifications' ? ' is-active' : '')
    }, m(Icon, {
      name: "fas fa-bell"
    }), m("span", null, t('hud.alerts')), unread ? m("span", {
      className: "DuskHud-dot",
      "aria-label": String(t('hud.unread', {
        count: unread
      }))
    }) : null) : null, user ? m(Link, {
      href: app.route.user(user),
      className: 'DuskHud-item' + (route?.startsWith('user') && app.current.get('user') === user ? ' is-active' : '')
    }, m(Avatar, {
      user: user,
      className: "DuskHud-avatar"
    }), m("span", null, t('hud.me'))) : m("button", {
      type: "button",
      className: "DuskHud-item",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, m(Icon, {
      name: "fas fa-right-to-bracket"
    }), m("span", null, app.translator.trans('core.forum.header.log_in_link'))));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/HudBar', HudBar);